SELECT account.module1_run_id,account.scenario_code,count(*)::bigint,count(*) FILTER(WHERE certification.state_certified_flag)::bigint,count(*) FILTER(WHERE account.reconciliation_outcome_code='NO_PAYMENT_ACTIVITY_RECONCILED')::bigint,count(*) FILTER(WHERE account.reconciliation_outcome_code='PAYMENT_ACTIVITY_RECONCILED_AFTER_RETRY')::bigint,count(*) FILTER(WHERE account.reconciliation_outcome_code='RECONCILIATION_REVIEW_HOLD')::bigint,sum(account.payment_event_count)::bigint,sum(account.exception_case_count)::bigint,sum(account.resolved_exception_count)::bigint,sum(account.unresolved_exception_count)::bigint,round(sum(account.scheduled_payment_amount),2),round(sum(account.processed_payment_amount),2),round(sum(account.returned_payment_amount),2),round(sum(account.retry_payment_amount),2),round(sum(account.reconciliation_variance_amount),2),round(sum(certification.certified_exposure_amount),2),round(sum(account.exposure_variance_amount),2),max(outcome.reconciliation_outcome_rank),NULL::text
FROM _m2_9_account_reconciliation_expected account JOIN _m2_9_certification_expected certification ON certification.module1_run_id=account.module1_run_id AND certification.scenario_id=account.scenario_id AND certification.merchant_application_id=account.merchant_application_id JOIN msbf_m2.payment_reconciliation_outcome_definition outcome ON outcome.module1_run_id=account.module1_run_id AND outcome.reconciliation_outcome_code=account.reconciliation_outcome_code GROUP BY account.module1_run_id,account.scenario_code;
