DO $portfolio_guard$ DECLARE v record; BEGIN SELECT count(*) portfolio_rows,sum(source_rows) source_rows,sum(certified_rows) certified_rows,sum(payment_event_rows) payment_rows,sum(exception_case_rows) exception_rows,sum(unresolved_exception_rows) unresolved_rows,round(sum(processed_payment_amount),2) processed_amount,round(sum(certified_exposure_amount),2) certified_exposure,round(sum(reconciliation_variance_amount),2) recon_variance,round(sum(exposure_variance_amount),2) exposure_variance INTO v FROM _m2_9_portfolio_expected; IF v.portfolio_rows<>2 OR v.source_rows<>59 OR v.certified_rows<>59 OR v.payment_rows<>7 OR v.exception_rows<>1 OR v.unresolved_rows<>0 OR v.processed_amount<>194.25 OR v.certified_exposure<>785.48 OR v.recon_variance<>0 OR v.exposure_variance<>0 THEN RAISE EXCEPTION 'M2.9 portfolio reconciliation failed: %.',row_to_json(v); END IF; END; $portfolio_guard$;
