 (SELECT md5(string_agg(row_hash,'|' ORDER BY resolution_action_rank,resolution_action_code)) FROM msbf_m2.exception_resolution_action_definition WHERE module1_run_id=(SELECT run_id FROM _m2_9_ctx)) resolution_action_set_hash,
 (SELECT md5(string_agg(row_hash,'|' ORDER BY certification_state_rank,certification_state_code)) FROM msbf_m2.account_state_certification_definition WHERE module1_run_id=(SELECT run_id FROM _m2_9_ctx)) certification_state_set_hash,
 (SELECT md5(string_agg(row_hash,'|' ORDER BY reconciliation_reason_code)) FROM msbf_m2.payment_reconciliation_reason_definition WHERE module1_run_id=(SELECT run_id FROM _m2_9_ctx)) reason_set_hash,
 (SELECT md5(string_agg(scenario_id::text||'|'||merchant_application_id||'|'||row_hash,'|' ORDER BY scenario_id,merchant_application_id)) FROM _m2_9_account_source_expected) account_source_set_hash,
 (SELECT md5(string_agg(scenario_id::text||'|'||merchant_application_id||'|'||event_sequence::text||'|'||row_hash,'|' ORDER BY scenario_id,merchant_application_id,event_sequence)) FROM _m2_9_payment_source_expected) payment_source_set_hash,
 (SELECT md5(string_agg(scenario_id::text||'|'||merchant_application_id||'|'||transition_sequence::text||'|'||row_hash,'|' ORDER BY scenario_id,merchant_application_id,transition_sequence)) FROM _m2_9_transition_source_expected) transition_source_set_hash,
 (SELECT md5(string_agg(scenario_id::text||'|'||merchant_application_id||'|'||event_sequence::text||'|'||row_hash,'|' ORDER BY scenario_id,merchant_application_id,event_sequence)) FROM _m2_9_payment_reconciliation_expected) payment_reconciliation_set_hash,
 (SELECT md5(string_agg(scenario_id::text||'|'||merchant_application_id||'|'||synthetic_exception_case_id||'|'||row_hash,'|' ORDER BY scenario_id,merchant_application_id,synthetic_exception_case_id)) FROM _m2_9_exception_expected) exception_case_set_hash,
 (SELECT md5(string_agg(scenario_id::text||'|'||merchant_application_id||'|'||row_hash,'|' ORDER BY scenario_id,merchant_application_id)) FROM _m2_9_account_reconciliation_expected) account_reconciliation_set_hash,
 (SELECT md5(string_agg(scenario_id::text||'|'||merchant_application_id||'|'||row_hash,'|' ORDER BY scenario_id,merchant_application_id)) FROM _m2_9_certification_expected) state_certification_set_hash,
 (SELECT md5(string_agg(scenario_code||'|'||row_hash,'|' ORDER BY scenario_code)) FROM _m2_9_portfolio_expected) portfolio_summary_set_hash,
 (SELECT md5(string_agg(scenario_id::text||'|'||merchant_application_id||'|'||contract_row_hash,'|' ORDER BY scenario_id,merchant_application_id)) FROM _m2_9_latest_expected) latest_set_hash,
 (SELECT md5(string_agg(scenario_id::text||'|'||merchant_application_id||'|'||archive_row_hash,'|' ORDER BY scenario_id,merchant_application_id)) FROM _m2_9_archive_expected) archive_set_hash;

