(SELECT count(*) FROM _m2_9_account_reconciliation_expected WHERE reconciliation_outcome_code='NO_PAYMENT_ACTIVITY_RECONCILED'),(SELECT count(*) FROM _m2_9_account_reconciliation_expected WHERE reconciliation_outcome_code='PAYMENT_ACTIVITY_RECONCILED_AFTER_RETRY'),(SELECT count(*) FROM _m2_9_account_reconciliation_expected WHERE reconciliation_outcome_code='RECONCILIATION_REVIEW_HOLD'),(SELECT count(*) FROM _m2_9_certification_expected WHERE certified_state_code='CERTIFIED_CLOSED_NO_PROCESSING'),(SELECT count(*) FROM _m2_9_certification_expected WHERE certified_state_code='CERTIFIED_REASSESSMENT_DUE_AFTER_RETRY'),(SELECT count(*) FROM _m2_9_certification_expected WHERE certified_state_code='CERTIFIED_REVIEW_HOLD'),(SELECT count(*) FROM _m2_9_payment_reconciliation_expected WHERE event_reconciliation_status_code='RECONCILED_SETTLED'),(SELECT count(*) FROM _m2_9_payment_reconciliation_expected WHERE event_reconciliation_status_code='RECONCILED_RETURN'),(SELECT count(*) FROM _m2_9_payment_reconciliation_expected WHERE event_reconciliation_status_code='RECONCILED_RETRY_SETTLED'),(SELECT count(*) FROM _m2_9_exception_expected),(SELECT count(*) FROM _m2_9_exception_expected WHERE exception_status_code='RESOLVED_BY_RETRY'),(SELECT count(*) FROM _m2_9_exception_expected WHERE unresolved_exception_flag),
(SELECT round(sum(scheduled_payment_amount),2) FROM _m2_9_account_reconciliation_expected),(SELECT round(sum(processed_payment_amount),2) FROM _m2_9_account_reconciliation_expected),(SELECT round(sum(returned_payment_amount),2) FROM _m2_9_account_reconciliation_expected),(SELECT round(sum(retry_payment_amount),2) FROM _m2_9_account_reconciliation_expected),(SELECT round(sum(exception_amount),2) FROM _m2_9_exception_expected),(SELECT round(sum(reconciliation_variance_amount),2) FROM _m2_9_account_reconciliation_expected),(SELECT round(sum(exposure_variance_amount),2) FROM _m2_9_account_reconciliation_expected),(SELECT round(sum(certified_exposure_amount),2) FROM _m2_9_certification_expected WHERE active_state_flag),(SELECT round(sum(certified_exposure_amount),2) FROM _m2_9_certification_expected WHERE review_hold_state_flag),(SELECT round(sum(certified_exposure_amount),2) FROM _m2_9_certification_expected),
hashes.policy_set_hash,hashes.reconciliation_outcome_set_hash,hashes.resolution_action_set_hash,hashes.certification_state_set_hash,hashes.reason_set_hash,hashes.account_source_set_hash,hashes.payment_source_set_hash,hashes.transition_source_set_hash,hashes.payment_reconciliation_set_hash,hashes.exception_case_set_hash,hashes.account_reconciliation_set_hash,hashes.state_certification_set_hash,hashes.portfolio_summary_set_hash,hashes.latest_set_hash,hashes.archive_set_hash,NULL::text,NULL::text,'GENERATED',clock_timestamp(),NULL::timestamptz,NULL::timestamptz,NULL::text
FROM _m2_9_ctx ctx CROSS JOIN _m2_9_hashes hashes;
UPDATE _m2_9_registry_expected registry SET row_hash=msbf_ctl.m2_9_registry_row_hash(to_jsonb(registry)) WHERE registry.row_hash IS NULL;
UPDATE _m2_9_registry_expected registry SET contract_set_hash=md5(registry.row_hash) WHERE registry.contract_set_hash IS NULL;

DROP TABLE IF EXISTS _m2_9_canonical_expected;
CREATE TEMP TABLE _m2_9_canonical_expected(entity_type text NOT NULL,entity_key text NOT NULL,row_hash text NOT NULL,PRIMARY KEY(entity_type,entity_key)) ON COMMIT DROP;
INSERT INTO _m2_9_canonical_expected
SELECT 'POLICY',policy_code||'|v'||policy_version::text,row_hash FROM msbf_ctl.m2_9_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m2_9_ctx)
UNION ALL SELECT 'RECONCILIATION_OUTCOME',reconciliation_outcome_code,row_hash FROM msbf_m2.payment_reconciliation_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m2_9_ctx)
UNION ALL SELECT 'RESOLUTION_ACTION',resolution_action_code,row_hash FROM msbf_m2.exception_resolution_action_definition WHERE module1_run_id=(SELECT run_id FROM _m2_9_ctx)
UNION ALL SELECT 'CERTIFICATION_STATE',certification_state_code,row_hash FROM msbf_m2.account_state_certification_definition WHERE module1_run_id=(SELECT run_id FROM _m2_9_ctx)
UNION ALL SELECT 'REASON_DEFINITION',reconciliation_reason_code,row_hash FROM msbf_m2.payment_reconciliation_reason_definition WHERE module1_run_id=(SELECT run_id FROM _m2_9_ctx)
UNION ALL SELECT 'ACCOUNT_SOURCE',scenario_id::text||'|'||merchant_application_id,row_hash FROM _m2_9_account_source_expected
UNION ALL SELECT 'PAYMENT_SOURCE',scenario_id::text||'|'||merchant_application_id||'|'||event_sequence::text,row_hash FROM _m2_9_payment_source_expected
UNION ALL SELECT 'TRANSITION_SOURCE',scenario_id::text||'|'||merchant_application_id||'|'||transition_sequence::text,row_hash FROM _m2_9_transition_source_expected
UNION ALL SELECT 'PAYMENT_RECONCILIATION',scenario_id::text||'|'||merchant_application_id||'|'||event_sequence::text,row_hash FROM _m2_9_payment_reconciliation_expected
UNION ALL SELECT 'EXCEPTION_CASE',scenario_id::text||'|'||merchant_application_id||'|'||synthetic_exception_case_id,row_hash FROM _m2_9_exception_expected
UNION ALL SELECT 'ACCOUNT_RECONCILIATION',scenario_id::text||'|'||merchant_application_id,row_hash FROM _m2_9_account_reconciliation_expected
UNION ALL SELECT 'STATE_CERTIFICATION',scenario_id::text||'|'||merchant_application_id,row_hash FROM _m2_9_certification_expected
UNION ALL SELECT 'PORTFOLIO_SUMMARY',scenario_code,row_hash FROM _m2_9_portfolio_expected
UNION ALL SELECT 'LATEST',scenario_id::text||'|'||merchant_application_id,contract_row_hash FROM _m2_9_latest_expected
UNION ALL SELECT 'ARCHIVE',scenario_id::text||'|'||merchant_application_id,archive_row_hash FROM _m2_9_archive_expected
UNION ALL SELECT 'REGISTRY',contract_code||'|v'||contract_version::text,row_hash FROM _m2_9_registry_expected;
UPDATE _m2_9_registry_expected registry SET combined_set_hash=(SELECT md5(string_agg(entity_type||'|'||entity_key||'|'||row_hash,'|' ORDER BY entity_type,entity_key)) FROM _m2_9_canonical_expected) WHERE registry.combined_set_hash IS NULL;
INSERT INTO msbf_ctl.m2_9_reconciliation_certification_contract_registry(
module1_run_id,contract_code,contract_version,schema_version,methodology_version,source_contract_code,source_contract_version,source_schema_version,source_acceptance_gate_id,source_combined_set_hash,policy_configuration_hash,policy_rows,reconciliation_outcome_rows,resolution_action_rows,certification_state_rows,reason_rows,account_source_rows,payment_source_rows,transition_source_rows,payment_reconciliation_rows,exception_case_rows,account_reconciliation_rows,state_certification_rows,portfolio_summary_rows,latest_rows,archive_rows,comparison_rows,registry_rows,canonical_entities,no_payment_activity_rows,reconciled_after_retry_rows,review_hold_rows,certified_closed_rows,certified_reassessment_rows,certified_review_hold_rows,settled_event_rows,returned_event_rows,retry_event_rows,exception_opened_rows,exception_resolved_rows,unresolved_exception_rows,scheduled_payment_amount,processed_payment_amount,returned_payment_amount,retry_payment_amount,exception_amount,reconciliation_variance_amount,exposure_variance_amount,active_certified_exposure_amount,review_hold_exposure_amount,portfolio_certified_exposure_amount,policy_set_hash,reconciliation_outcome_set_hash,resolution_action_set_hash,certification_state_set_hash,reason_set_hash,account_source_set_hash,payment_source_set_hash,transition_source_set_hash,payment_reconciliation_set_hash,exception_case_set_hash,account_reconciliation_set_hash,state_certification_set_hash,portfolio_summary_set_hash,latest_set_hash,archive_set_hash,contract_set_hash,combined_set_hash,contract_status,generated_at,validated_at,accepted_at,row_hash)
SELECT module1_run_id,contract_code,contract_version,schema_version,methodology_version,source_contract_code,source_contract_version,source_schema_version,source_acceptance_gate_id,source_combined_set_hash,policy_configuration_hash,policy_rows,reconciliation_outcome_rows,resolution_action_rows,certification_state_rows,reason_rows,account_source_rows,payment_source_rows,transition_source_rows,payment_reconciliation_rows,exception_case_rows,account_reconciliation_rows,state_certification_rows,portfolio_summary_rows,latest_rows,archive_rows,comparison_rows,registry_rows,canonical_entities,no_payment_activity_rows,reconciled_after_retry_rows,review_hold_rows,certified_closed_rows,certified_reassessment_rows,certified_review_hold_rows,settled_event_rows,returned_event_rows,retry_event_rows,exception_opened_rows,exception_resolved_rows,unresolved_exception_rows,scheduled_payment_amount,processed_payment_amount,returned_payment_amount,retry_payment_amount,exception_amount,reconciliation_variance_amount,exposure_variance_amount,active_certified_exposure_amount,review_hold_exposure_amount,portfolio_certified_exposure_amount,policy_set_hash,reconciliation_outcome_set_hash,resolution_action_set_hash,certification_state_set_hash,reason_set_hash,account_source_set_hash,payment_source_set_hash,transition_source_set_hash,payment_reconciliation_set_hash,exception_case_set_hash,account_reconciliation_set_hash,state_certification_set_hash,portfolio_summary_set_hash,latest_set_hash,archive_set_hash,contract_set_hash,combined_set_hash,contract_status,generated_at,validated_at,accepted_at,row_hash FROM _m2_9_registry_expected;

DROP TABLE IF EXISTS _m2_9_mismatch;
CREATE TEMP TABLE _m2_9_mismatch ON COMMIT DROP AS SELECT coalesce(expected.entity_type,actual.entity_type) entity_type,coalesce(expected.entity_key,actual.entity_key) entity_key,expected.row_hash expected_hash,actual.row_hash actual_hash FROM _m2_9_canonical_expected expected FULL OUTER JOIN(SELECT entity_type,entity_key,row_hash FROM msbf_m2.v_m2_9_canonical_entity WHERE module1_run_id=(SELECT run_id FROM _m2_9_ctx)) actual ON actual.entity_type=expected.entity_type AND actual.entity_key=expected.entity_key WHERE expected.row_hash IS DISTINCT FROM actual.row_hash;
DROP TABLE IF EXISTS _m2_9_diagnostics;
CREATE TEMP TABLE _m2_9_diagnostics ON COMMIT PRESERVE ROWS AS SELECT (SELECT count(*) FROM _m2_9_canonical_expected)::bigint expected_canonical_entities,(SELECT count(*) FROM msbf_m2.v_m2_9_canonical_entity WHERE module1_run_id=(SELECT run_id FROM _m2_9_ctx))::bigint actual_canonical_entities,(SELECT count(*) FROM _m2_9_mismatch)::bigint row_level_mismatches,(SELECT count(*) FROM msbf_m2.v_m2_9_matched_scenario_comparison WHERE module1_run_id=(SELECT run_id FROM _m2_9_ctx))::bigint comparison_rows,(SELECT count(*) FROM msbf_m2.v_m2_9_matched_scenario_comparison WHERE module1_run_id=(SELECT run_id FROM _m2_9_ctx) AND stress_certification_permission_improvement_flag)::bigint stress_certification_permission_improvements,(SELECT count(*) FROM msbf_m2.v_m2_9_matched_scenario_comparison WHERE module1_run_id=(SELECT run_id FROM _m2_9_ctx) AND stress_certification_rank_improvement_flag)::bigint stress_certification_rank_improvements,(SELECT count(*) FROM msbf_m2.v_m2_9_matched_scenario_comparison WHERE module1_run_id=(SELECT run_id FROM _m2_9_ctx) AND stress_exposure_improvement_flag)::bigint stress_exposure_improvements;
DO $recon_guard$ DECLARE v record; BEGIN SELECT * INTO v FROM _m2_9_diagnostics; IF v.expected_canonical_entities<>438 OR v.actual_canonical_entities<>438 OR v.row_level_mismatches<>0 OR v.comparison_rows<>15 OR v.stress_certification_permission_improvements<>0 OR v.stress_certification_rank_improvements<>0 OR v.stress_exposure_improvements<>0 THEN RAISE EXCEPTION 'M2.9 deterministic reconciliation failed: %.',row_to_json(v); END IF; END; $recon_guard$;

DROP TABLE IF EXISTS _m2_9_generation_evidence;
CREATE TEMP TABLE _m2_9_generation_evidence(run_id bigint NOT NULL,evidence_code text NOT NULL,segment_key text NOT NULL,metric_name text NOT NULL,metric_value_numeric numeric(28,10),metric_value_text text,unit_code text NOT NULL,status text NOT NULL,interpretation text NOT NULL,CHECK(num_nonnulls(metric_value_numeric,metric_value_text)=1)) ON COMMIT DROP;
INSERT INTO _m2_9_generation_evidence
SELECT registry.module1_run_id,e.code,'PORTFOLIO',e.metric,e.num,e.txt,e.unit,'PASS',e.note FROM _m2_9_registry_expected registry CROSS JOIN LATERAL(VALUES
('M2_9_POLICY_SET_HASH','POLICY_SET_HASH',NULL::numeric(28,10),registry.policy_set_hash,'HASH','Policy set hash.'),('M2_9_OUTCOME_SET_HASH','OUTCOME_SET_HASH',NULL::numeric(28,10),registry.reconciliation_outcome_set_hash,'HASH','Reconciliation outcome set hash.'),('M2_9_ACTION_SET_HASH','ACTION_SET_HASH',NULL::numeric(28,10),registry.resolution_action_set_hash,'HASH','Resolution action set hash.'),('M2_9_CERTIFICATION_SET_HASH','CERTIFICATION_SET_HASH',NULL::numeric(28,10),registry.certification_state_set_hash,'HASH','Certification state definition hash.'),('M2_9_REASON_SET_HASH','REASON_SET_HASH',NULL::numeric(28,10),registry.reason_set_hash,'HASH','Reason set hash.'),('M2_9_ACCOUNT_SOURCE_SET_HASH','ACCOUNT_SOURCE_SET_HASH',NULL::numeric(28,10),registry.account_source_set_hash,'HASH','Account source set hash.'),('M2_9_PAYMENT_SOURCE_SET_HASH','PAYMENT_SOURCE_SET_HASH',NULL::numeric(28,10),registry.payment_source_set_hash,'HASH','Payment source set hash.'),('M2_9_TRANSITION_SOURCE_SET_HASH','TRANSITION_SOURCE_SET_HASH',NULL::numeric(28,10),registry.transition_source_set_hash,'HASH','Transition source set hash.'),('M2_9_PAYMENT_RECONCILIATION_SET_HASH','PAYMENT_RECONCILIATION_SET_HASH',NULL::numeric(28,10),registry.payment_reconciliation_set_hash,'HASH','Payment reconciliation set hash.'),('M2_9_EXCEPTION_CASE_SET_HASH','EXCEPTION_CASE_SET_HASH',NULL::numeric(28,10),registry.exception_case_set_hash,'HASH','Exception case set hash.'),('M2_9_ACCOUNT_RECONCILIATION_SET_HASH','ACCOUNT_RECONCILIATION_SET_HASH',NULL::numeric(28,10),registry.account_reconciliation_set_hash,'HASH','Account reconciliation set hash.'),('M2_9_STATE_CERTIFICATION_SET_HASH','STATE_CERTIFICATION_SET_HASH',NULL::numeric(28,10),registry.state_certification_set_hash,'HASH','State certification set hash.'),('M2_9_LATEST_SET_HASH','LATEST_SET_HASH',NULL::numeric(28,10),registry.latest_set_hash,'HASH','Latest set hash.'),('M2_9_COMBINED_SET_HASH','COMBINED_SET_HASH',NULL::numeric(28,10),registry.combined_set_hash,'HASH','Combined canonical set hash.'),
('M2_9_ACCOUNT_SOURCE_ROWS','ACCOUNT_SOURCE_ROWS',registry.account_source_rows::numeric(28,10),NULL::text,'ROWS','Account source rows.'),('M2_9_PAYMENT_SOURCE_ROWS','PAYMENT_SOURCE_ROWS',registry.payment_source_rows::numeric(28,10),NULL::text,'ROWS','Payment source rows.'),('M2_9_TRANSITION_SOURCE_ROWS','TRANSITION_SOURCE_ROWS',registry.transition_source_rows::numeric(28,10),NULL::text,'ROWS','Transition source rows.'),('M2_9_ACCOUNT_RECONCILIATION_ROWS','ACCOUNT_RECONCILIATION_ROWS',registry.account_reconciliation_rows::numeric(28,10),NULL::text,'ROWS','Account reconciliation rows.'),('M2_9_STATE_CERTIFICATION_ROWS','STATE_CERTIFICATION_ROWS',registry.state_certification_rows::numeric(28,10),NULL::text,'ROWS','State certification rows.'),('M2_9_EXCEPTION_CASE_ROWS','EXCEPTION_CASE_ROWS',registry.exception_case_rows::numeric(28,10),NULL::text,'ROWS','Exception case rows.'),('M2_9_CANONICAL_ENTITIES','CANONICAL_ENTITIES',registry.canonical_entities::numeric(28,10),NULL::text,'ROWS','Canonical entities.'),('M2_9_PROCESSED_AMOUNT','PROCESSED_AMOUNT',registry.processed_payment_amount::numeric(28,10),NULL::text,'USD','Processed amount.'),('M2_9_CERTIFIED_EXPOSURE','CERTIFIED_EXPOSURE',registry.portfolio_certified_exposure_amount::numeric(28,10),NULL::text,'USD','Certified exposure.'),('M2_9_UNRESOLVED_EXCEPTION_ROWS','UNRESOLVED_EXCEPTION_ROWS',registry.unresolved_exception_rows::numeric(28,10),NULL::text,'ROWS','Unresolved exception rows.')) e(code,metric,num,txt,unit,note);
INSERT INTO msbf_ctl.run_evidence(run_id,evidence_code,segment_key,metric_name,metric_value_numeric,metric_value_text,unit_code,status,interpretation)
SELECT run_id,evidence_code,segment_key,metric_name,metric_value_numeric,metric_value_text,unit_code,status,interpretation FROM _m2_9_generation_evidence;
UPDATE msbf_ctl.run_registry SET run_status='M2_9_GENERATED',notes=coalesce(notes,'')||' | M2.9 payment reconciliation, exception resolution, and account-state certification generated.' WHERE run_id=(SELECT run_id FROM _m2_9_ctx);
INSERT INTO _m2_9_result
SELECT registry.module1_run_id,'M2_9_GENERATED',registry.policy_rows,registry.reconciliation_outcome_rows,registry.resolution_action_rows,registry.certification_state_rows,registry.reason_rows,registry.account_source_rows,registry.payment_source_rows,registry.transition_source_rows,registry.payment_reconciliation_rows,registry.exception_case_rows,registry.account_reconciliation_rows,registry.state_certification_rows,registry.portfolio_summary_rows,registry.latest_rows,registry.archive_rows,registry.comparison_rows,registry.registry_rows,registry.no_payment_activity_rows,registry.reconciled_after_retry_rows,registry.review_hold_rows,registry.certified_closed_rows,registry.certified_reassessment_rows,registry.certified_review_hold_rows,registry.settled_event_rows,registry.returned_event_rows,registry.retry_event_rows,registry.exception_opened_rows,registry.exception_resolved_rows,registry.unresolved_exception_rows,registry.scheduled_payment_amount,registry.processed_payment_amount,registry.returned_payment_amount,registry.retry_payment_amount,registry.exception_amount,registry.reconciliation_variance_amount,registry.exposure_variance_amount,registry.active_certified_exposure_amount,registry.review_hold_exposure_amount,registry.portfolio_certified_exposure_amount,438,diagnostics.actual_canonical_entities,diagnostics.row_level_mismatches,diagnostics.stress_certification_permission_improvements,diagnostics.stress_certification_rank_improvements,diagnostics.stress_exposure_improvements,registry.policy_set_hash,registry.reconciliation_outcome_set_hash,registry.resolution_action_set_hash,registry.certification_state_set_hash,registry.reason_set_hash,registry.account_source_set_hash,registry.payment_source_set_hash,registry.transition_source_set_hash,registry.payment_reconciliation_set_hash,registry.exception_case_set_hash,registry.account_reconciliation_set_hash,registry.state_certification_set_hash,registry.portfolio_summary_set_hash,registry.latest_set_hash,registry.archive_set_hash,registry.contract_set_hash,registry.combined_set_hash,'PASS'
FROM msbf_ctl.m2_9_reconciliation_certification_contract_registry registry CROSS JOIN _m2_9_diagnostics diagnostics WHERE registry.module1_run_id=(SELECT run_id FROM _m2_9_ctx);
COMMIT;
SELECT * FROM _m2_9_result;
